import model from './gaze-intent-model.json'

// Model features and normalization are generated by backend/ml/train_gaze_mode.py.
export function estimateGazeMode(points) {
  if (!Array.isArray(points) || points.length < 12) return null
  const duration = (points.at(-1).at - points[0].at) / 1000
  if (duration < 800) return null

  const xs = points.map(point => point.x)
  const ys = points.map(point => point.y)
  const mean = values => values.reduce((sum, value) => sum + value, 0) / values.length
  const standardDeviation = values => {
    const average = mean(values)
    return Math.sqrt(mean(values.map(value => (value - average) ** 2)))
  }
  let pathLength = 0
  for (let i = 1; i < points.length; i++) {
    pathLength += Math.hypot(points[i].x - points[i - 1].x, points[i].y - points[i - 1].y)
  }
  const features = [standardDeviation(xs), standardDeviation(ys), pathLength / duration, mean(xs), mean(ys)]
  const normalized = features.map((value, index) => (value - model.means[index]) / model.scales[index])
  const logit = model.weights[0] + normalized.reduce((sum, value, index) => sum + value * model.weights[index + 1], 0)
  const structuredProbability = 1 / (1 + Math.exp(-Math.max(-30, Math.min(30, logit))))
  return { structuredProbability }
}
